### Iteration 4 — Abstraction
```js
// 🏁 Sprint 4  ─────────────────────────────────────────────
// Goal: Shield consumers from low-level Fetch API details through a
// higher-level abstraction (a tiny HTTP client).
//
export async function http(endpoint, { method = 'GET', body, token } = {}) {
  const headers = { 'Content-Type': 'application/json' };
  if (token) headers['Authorization'] = `Bearer ${token}`;

  const res = await fetch(endpoint, {
    method,
    headers,
    body: body ? JSON.stringify(body) : undefined
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

// Usage	in UI layer (hides headers, errors, serialization)
import { http } from './http.js';
const data = await http('/api/profile');
```
*Sprint Review:* Abstraction paid off when the backend adopted GraphQL; only **http()** changed.

