### Iteration 5 — State Management (Unidirectional Flow)
```js
// 🏁 Sprint 5  ─────────────────────────────────────────────
// Implement a minimal Redux-like store to centralize state.
//
function createStore(reducer, initialState) {
  let state = initialState;
  const listeners = new Set();
  return {
    dispatch(action){ state = reducer(state, action); listeners.forEach(l => l()); },
    subscribe(fn){ listeners.add(fn); return () => listeners.delete(fn); },
    getState(){ return state; }
  };
}

// Reducer
function counterReducer(state = { count:0 }, action){
  switch(action.type){
    case 'INC': return { count: state.count + 1 };
    default: return state;
  }
}

// Instantiate
const store = createStore(counterReducer);

// View binding (no two-way data binding => predictable!)
store.subscribe(() => document.body.textContent = store.getState().count);
document.body.onclick = () => store.dispatch({type:'INC'});
```
*Burndown Chart* showed steady progress; no scope creep.

